mapper.select:
select count(distinct l.client_ip)
from biz_access_log l


        inner join biz_query q on q.query_id = l.target_id
        and q.create_user_id = #{createUserId}


        inner join biz_survey s on s.survey_id = l.target_id
        and s.create_user_id = #{createUserId}


where l.target_type = #{targetType}
  and l.action = #{action}
  and l.client_ip is not null
  and l.client_ip <> ''

  and l.create_time >= current_date

select log_id, target_type, target_id, public_code, action, client_ip, user_agent, detail_json, create_time
from biz_access_log
where target_type = #{targetType}
  and target_id = #{targetId}

  and action = #{action}

order by create_time desc, log_id desc
limit #{limit}
